import { createPayment, reconcile, STATUSES } from './engine.js';

const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtMoney = value => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(value)||0);
const fmtTime = iso => new Intl.DateTimeFormat('en-IN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(iso));
const state = { transactions:[], selectedId:null, usedKeys:new Set(), lastRecon:null, counter:1, glossaryFilter:'All', lastFocus:null, traceTimer:null };
const statusMeta = {SUCCESS:['Successful','success'],DECLINED:['Declined','declined'],PENDING_REVIEW:['Pending review','pending'],VALIDATION_FAILED:['Validation failed','invalid']};

