const detailData = {
  fintech:{category:'FOUNDATION',title:'What is FinTech?',lede:'FinTech means financial technology: technology used to deliver, improve or operate financial services. It is not one product, one app or one payment rail.',sections:[['In plain English','If you check a balance on a phone, apply for a loan online, pay a shop using a QR code, buy insurance through an app or use software that helps a small business manage invoices, you are interacting with financial technology.'],['Why it exists','Finance depends on information, trust, rules and the movement or management of money. Technology can make parts of that work faster, easier to access, more automated or easier to analyse. It can also introduce cyber risk, exclusion, outages, privacy concerns and new forms of fraud.'],['What belongs to FinTech?','Payments and transfers; digital banking; lending and credit scoring; insurance technology; investment and wealth platforms; personal finance; regulatory technology; financial data infrastructure; identity and fraud controls; embedded finance; digital assets and more.'],['What it is not','A financial app is an interface, not the entire system. An API is a software interface, not a payment network. Blockchain is one type of technology, not a synonym for all FinTech. A digital service may still rely on traditional banks and established financial infrastructure.'],['A useful way to think about it','Ask: which financial problem is being addressed, who participates, what technology is involved, who is accountable, how does value move, what rules apply, and what happens when the system fails?']]},
  'route-upi':{category:'PAYMENT ROUTE · INDIA',title:'UPI: a payment instruction between bank accounts',lede:'UPI lets a customer initiate a payment through a participating app using an address, QR code or other supported method. The app experience is only one part of the underlying bank and payment-system coordination.',sections:[['A simplified journey','The customer confirms the payee and amount in the app. The app and its payment service send an instruction through the relevant UPI participant. The payer’s bank applies the required checks and responds; the payment system coordinates the instruction and the receiving side is notified according to system rules.'],['What is being checked?','Payee details, account or payment address resolution, authentication, transaction limits, risk signals and the payer’s available funds may be relevant. Exact checks and routing depend on the participating institutions and current rules.'],['What the customer sees','A success, failure or pending message. A pending or timed-out response should not automatically be treated as proof of failure; the authoritative status should be checked before retrying.'],['Important distinction','UPI is a payment system, not a bank account, wallet or single app. Participating apps and banks have different roles. App confirmation, bank records, settlement and reconciliation are related but not identical.']],refs:['npci','rbiPayments']},
  'route-card':{category:'PAYMENT ROUTE · CARDS',title:'Card payments: authorisation is not the whole journey',lede:'A card transaction usually connects the merchant, acquiring side, card network and issuing bank. The exact route depends on the card product, merchant setup and scheme rules.',sections:[['A simplified journey','The customer presents a card or token. The merchant’s payment service sends an authorisation request through its acquirer and the card network to the issuer. The issuer returns an approval or decline. Later processes handle clearing, settlement and reconciliation under the relevant rules.'],['What is checked?','Card or token validity, authentication where required, available credit or funds, fraud signals, merchant details and issuer rules may affect the decision. Approval is not a guarantee against later disputes or reversals.'],['Fees and records','Merchant service charges and other fees depend on the agreement, market, card type and transaction. The customer’s statement, merchant payout and network settlement records may update at different times.'],['If something goes wrong','A timeout can leave the outcome uncertain. Duplicate attempts, reversals, refunds and chargebacks have separate rules; a refund is not simply the same event as cancelling an authorisation.']],refs:['rbiPayments']},
  'route-bank':{category:'PAYMENT ROUTE · INDIA',title:'IMPS, NEFT and RTGS: related, but not identical',lede:'These are bank transfer systems in India with different operating models and rules. They should not be described as one generic workflow or assumed to have identical timing and settlement behaviour.',sections:[['IMPS','Immediate Payment Service supports round-the-clock electronic fund transfers through participating institutions, subject to the service and participant rules. It is commonly used for time-sensitive retail transfers.'],['NEFT','National Electronic Funds Transfer operates continuously, with transactions processed in half-hourly batches under the system’s current arrangements. “Available 24×7” does not mean every technical step is identical to an individual real-time gross settlement.'],['RTGS','Real Time Gross Settlement processes eligible transfers individually in real time. It is designed for high-value transfers and has system-specific minimums, rules and settlement arrangements. Check the current RBI guidance for applicable details.'],['Before comparing','Check the transfer amount, beneficiary details, bank cut-offs or service availability, charges, limits and the status shown by the bank. A confirmation message should be interpreted in the context of the specific system.']],refs:['rbiPayments','rbi']},
  'route-crossborder':{category:'PAYMENT ROUTE · INTERNATIONAL',title:'Cross-border payments: one instruction, several possible routes',lede:'International payments can involve more than a sender and a recipient. The route depends on the currency pair, provider, corridor, local systems and compliance requirements.',sections:[['A possible journey','The sender gives an instruction and sees a quoted fee and exchange rate. The provider verifies details and performs applicable screening. Funds and payment messages may pass through correspondent institutions or other arrangements; a local payment system or payout partner may then deliver funds to the recipient. Not every route uses every participant.'],['Where cost and time come from','Provider fees, foreign-exchange spread, intermediary charges, operating hours, compliance checks and the recipient-side payout method can affect the amount received and delivery time. A displayed mid-market rate is not necessarily the rate offered to a customer.'],['What should be transparent','The sender should be able to understand the expected amount received, applicable fees and exchange rate, estimated delivery time and what happens if details are wrong or the transfer is delayed. Exact disclosure requirements vary by jurisdiction and product.'],['Why the status can be complex','A provider may have accepted an instruction before the recipient’s account is credited. Messaging, funding, settlement and final payout are separate parts of some routes.']],refs:['bis','fsb','worldbank']},
  customer:{category:'ARCHITECTURE · NODE 01',title:'Customer, merchant or business',lede:'Every financial workflow starts with an intention: pay, receive, borrow, save, insure, invest or check information.',sections:[['What this component does','The customer or business initiates an instruction, provides relevant information and may give consent or authentication. A merchant may create an order and ask a payment service to collect funds.'],['What information is involved?','Depending on the product: amount, currency, recipient, account or payment token, order reference, device context and authentication evidence. Sensitive information should be minimised and protected.'],['What can go wrong?','A mistaken recipient, social-engineering scam, compromised device, misleading consent screen or inaccessible interface can cause harm before a transaction reaches the underlying financial infrastructure.'],['Why it matters','Good system design includes understandable confirmation screens, accessible language, clear fees and safe recovery paths. The user experience is part of financial safety, not just decoration.']]},
  application:{category:'ARCHITECTURE · NODE 02',title:'Mobile app or web browser',lede:'The interface is the place where a person interacts with a service. It presents information and sends requests, but it is not necessarily where the core financial decision is made.',sections:[['Mobile applications','Apps can use device features such as biometrics, secure storage and push notifications, subject to platform controls. They need secure update practices and careful handling of tokens and session state.'],['Web browsers','A browser loads a web interface and communicates with back-end services over network protocols such as HTTPS. A browser-based experience can be convenient across devices, but session management, phishing resistance and browser security still matter.'],['What the interface should show','Clear amount and recipient, fees where applicable, consent, status, next steps and a usable way to handle uncertainty. “Pending” should not be shown as “failed” unless the system has evidence of failure.'],['Behind the screen','The application typically calls back-end services. Those services may call APIs, identity providers, core banking platforms, payment gateways, risk engines or other systems. The exact architecture varies.']]},
  api:{category:'ARCHITECTURE · TECHNOLOGY',title:'API: the agreed way software talks',lede:'An Application Programming Interface (API) defines how one software component can request information or an action from another component.',sections:[['Simple example','A budgeting app may ask a bank service for a balance, with the customer’s permission and under the relevant access rules. The API defines the request format, required credentials, possible responses and error behaviour.'],['What an API is not','It is not automatically a bank, a payment rail, a database or a settlement process. It is a communication contract between software components. A payment API may initiate a request, but other systems decide what happens next.'],['A typical request journey','Application → secure API endpoint → authentication and authorisation → business logic → downstream service or data store → response. Production systems also need rate limits, monitoring, access control, versioning and safe error handling.'],['Common failure modes','Expired credentials, invalid payloads, rate limits, network timeouts, duplicate submissions, incompatible versions or downstream outages. A timeout can leave the caller unsure whether the requested action completed.'],['Related terminology','HTTPS, endpoint, JSON, OAuth, webhook, idempotency, API gateway and service-level objective. Search these in the Terminology tab.']]},
  provider:{category:'ARCHITECTURE · NODE 04',title:'Bank, fintech provider or financial institution',lede:'A provider supplies a financial service under a particular business model, contract and regulatory framework.',sections:[['Different roles','A bank may hold deposits and maintain customer accounts. A payment service provider may help a merchant accept payments. A lender makes or arranges credit. An insurer underwrites risk. A fintech company may build technology, distribute a product or partner with a regulated institution.'],['Do not assume one company does everything','The app brand, licensed institution, processor, payment network, data provider and customer support team may be different organisations. Their responsibilities depend on the product and agreements.'],['Legacy and modern systems','Many established institutions run core systems built over decades alongside APIs, mobile apps, cloud services and analytics platforms. Modernisation often means connecting and gradually replacing components rather than switching everything overnight.'],['Questions to ask','Who holds the customer relationship? Who holds funds or bears credit/insurance risk? Who handles complaints? Who is regulated for this activity? Who is responsible when a partner or dependency fails?']]},
  network:{category:'ARCHITECTURE · NODE 05',title:'Payment network or rail',lede:'A payment rail is the infrastructure and rule set through which payment instructions or value transfers are routed and processed. Different rails work differently.',sections:[['Examples','India has UPI, IMPS, NEFT and RTGS, as well as card networks and other systems. Other countries operate their own instant payment systems, clearing arrangements and card networks. International transfers can use multiple arrangements.'],['Why the distinction matters','Some systems process payments individually in real time; others use batches or scheduled settlement. Some provide an immediate confirmation while settlement and reconciliation steps differ. Cards include issuer/acquirer and network roles; bank transfers follow their own rules.'],['What a rail does not tell you','The rail name alone does not fully explain the app experience, fraud checks, fees, dispute rights, timing, settlement model or exact finality. Those depend on scheme rules, participants and jurisdiction.'],['Explore authoritative information','NPCI publishes UPI information; RBI publishes payment-system regulations and reports; central banks and scheme operators in other markets document their systems. See References.']]},
  controls:{category:'ARCHITECTURE · NODE 06',title:'Risk and compliance controls',lede:'Controls help a service manage fraud, identity, financial crime, security and legal obligations. They should be proportionate, explainable where possible and monitored for unintended harm.',sections:[['Examples of controls','Authentication, transaction limits, velocity checks, device risk, fraud models, sanctions screening where applicable, KYC processes, anti-money-laundering monitoring and human review. Not every control applies to every product.'],['Possible outcomes','Allow, ask for stronger authentication, delay, place a hold, reject or escalate for investigation. A suspicious signal is not always proof of wrongdoing. Screening systems can produce false positives.'],['Trade-offs','Stronger checks can reduce certain risks but may add friction, delay legitimate customers or exclude people with limited documentation or device access. Poorly governed models can create unfair outcomes.'],['Indian context','Requirements depend on the activity and regulated entity. RBI, SEBI, IRDAI, PFRDA, data-protection authorities and other bodies have different remits. NPCI operates payment systems but is not a substitute for the regulator. Check current primary rules.']]},
  ledger:{category:'ARCHITECTURE · NODE 07',title:'Ledger and transaction records',lede:'A ledger records financial positions or movements. Event logs record what a system observed. They are related, but they are not the same thing.',sections:[['Ledger in plain English','A ledger is a structured record used to represent balances, obligations or financial movements. Different institutions maintain different ledgers for different purposes. Accounting systems may use double-entry principles.'],['Event log','An event log might say a request arrived at 10:03:04, a risk check ran, a response timed out or a record was updated. It helps reconstruct what happened and when.'],['Why references matter','A stable transaction identifier lets systems correlate requests, events, ledger entries, provider references and settlement reports. Without reliable identifiers, investigation becomes harder.'],['What can go wrong?','Missing, duplicated, delayed or inconsistent records; incorrect amounts; mismatched currency; incorrect status mapping; or logs that omit necessary context. Logs also need access controls and privacy protections.']]},
  reconciliation:{category:'OPERATIONS · RECORDS',title:'Reconciliation: do the records agree?',lede:'Reconciliation compares records from different systems or sources to identify matches and exceptions. It does not automatically explain every difference.',sections:[['Example','A merchant’s order system says a customer paid ₹1,000. The payment provider report shows a transaction for ₹1,000, but the internal ledger has no matching entry. Reconciliation flags the missing match for investigation.'],['What gets compared?','Identifiers, amount, currency, status, timestamps, fees, settlement batch and counterparty references, depending on the process. Matching rules need to account for timing differences and legitimate adjustments.'],['What happens after an exception?','Investigators identify whether it is a timing issue, mapping issue, missing event, duplicate, fee difference, reversal or real financial discrepancy. The resolution is recorded with evidence.'],['Why it matters','Without reconciliation, a service can display the wrong state, misreport balances, fail to pay a merchant correctly or miss an operational problem. The right process depends on the product and settlement model.']]},
  connection:{category:'SYSTEM MAP · CONNECTOR',title:'What moves through a connection?',lede:'A connector represents an interaction between two components. The information crossing it depends on the architecture; not every connection carries money itself.',sections:[['Common payloads','A request, response, status message, identity assertion, consent record, risk signal, payment instruction, transaction reference or settlement report. Some connections transmit messages about money rather than moving the funds themselves.'],['Ask four questions','Who sends the information? Who receives it? How is it authenticated and protected? What does the sender do if the response is missing or contradictory?'],['Why arrows matter','The direction of a message is not always the direction of money. An authorisation request and response may travel in opposite directions; clearing files and settlement movements can use separate systems.'],['Try it','Select the API, provider, rail and ledger nodes. Compare their roles. Then run the payment simulator to see an illustrative event trail.']]},
  corebanking:{category:'ARCHITECTURE · LEGACY & MODERN',title:'Core banking systems',lede:'Core banking software supports essential bank operations such as customer accounts, balances, deposits, loans and transaction posting. The exact capabilities differ by bank and platform.',sections:[['Why it matters','Mobile and web banking often depend on core systems to retrieve balances, validate account status or post transactions. A polished app does not remove the need for accurate underlying records.'],['Why legacy modernisation is hard','Core systems may support critical workloads and years of business rules. Replacing them carries migration, continuity, data integrity, integration and operational risks. Banks often modernise incrementally.'],['Modernisation patterns','API layers, event streaming, cloud services, data platforms and modular services can connect older systems to new channels. These approaches also introduce dependency management and security challenges.'],['Trade-off','Keeping an old system can constrain speed and flexibility; replacing it can be expensive and risky. The right path depends on resilience, cost, architecture, regulatory expectations and business priorities.']]},
  security:{category:'ARCHITECTURE · TRUST',title:'Identity, authentication and authorisation',lede:'These terms are related but different: identity is who someone claims to be, authentication checks a claim, and authorisation determines what an authenticated actor is allowed to do.',sections:[['Authentication','A system checks evidence such as a password, one-time code, device-bound credential or biometric verification through a trusted mechanism. A biometric match may unlock a credential; it does not itself settle a payment.'],['Authorisation','The system checks whether a requested action is permitted: for example, whether a user or service may access a particular account or initiate a transaction under the applicable rules. Payment authorisation has a more specific meaning in card and payment contexts.'],['Consent and privacy','A customer should understand what data is being accessed, for what purpose, by whom and under what terms. Consent flows should be clear, revocable where applicable and not misleading.'],['Security controls','Least privilege, encryption in transit and at rest, secure secrets, monitoring, rate limits, safe logging, incident response and testing are part of a wider security programme. No single control makes a system secure.']]},
  crossborder:{category:'GLOBAL PAYMENTS',title:'A cross-border payment has layers',lede:'A cross-border payment moves value or a payment instruction between parties in different countries or currency areas. It may involve several providers and legal frameworks.',sections:[['A simplified journey','Sender and provider → identity and compliance checks → quote and currency conversion → routing through relevant institutions or networks → processing in the receiving market → recipient credit → records and reconciliation.'],['Why it can be complicated','Different operating hours, currencies, account formats, local payment systems, intermediary institutions, screening requirements, data standards, fees and status messages can all matter. Not every route uses every layer.'],['What the user should see','Total fees, exchange rate and margin where applicable, expected delivery time, recipient amount, tracking/status, terms and what to do if the payment is delayed. These are central transparency questions in global policy work.'],['Evidence and policy','The FSB’s G20 targets address cost, speed, access and transparency. They are targets for improvement, not a statement that every corridor already achieves them. See the FSB link in References.']]},
  correspondent:{category:'CROSS-BORDER ROUTE',title:'Correspondent banking',lede:'A bank may use an account relationship with another bank to make or receive payments in a market or currency where it does not have direct access.',sections:[['Simple analogy','If Bank A cannot directly settle in a particular currency or reach a local payment system, it may use a correspondent bank that can provide the relevant access. More than one intermediary can be involved, depending on the route.'],['What happens behind the scenes','Instructions are exchanged, account relationships and balances matter, compliance checks are applied, and payment obligations are settled through relevant arrangements. Messaging and movement of funds are distinct concepts.'],['Trade-offs','Correspondent relationships enable broad reach but can add cost, processing steps, operational dependencies and transparency challenges. Not every cross-border payment uses correspondent banking.'],['Useful source','The BIS and FSB publish work on cross-border payment frictions, interoperability and regulatory coordination. SWIFT provides financial messaging infrastructure; messaging is not itself the settlement of funds.']]},
  remittance:{category:'CROSS-BORDER ROUTE',title:'Remittances',lede:'A remittance is a transfer of money, often from a person working or living abroad to a recipient elsewhere. It may be sent through a bank, money transfer operator or other authorised provider.',sections:[['Typical flow','Sender selects a recipient and funding method, receives a quote, completes required checks, pays the provider, and the provider routes the transfer to a payout partner or account. The recipient is credited or paid through the selected method.'],['Costs','The total cost can include a transfer fee, exchange-rate margin and, depending on the route, receiving or intermediary charges. Compare the amount the recipient gets, not only the headline fee.'],['Timing and uncertainty','Delivery time depends on provider, corridor, funding method, compliance review, local payment systems and business hours. A displayed estimate is not a guarantee.'],['Source for comparisons','The World Bank’s Remittance Prices Worldwide database tracks remittance costs across corridors. Always check the collection date and method used.']]},
  cardcross:{category:'CROSS-BORDER ROUTE',title:'International card payment',lede:'A card purchase can involve the merchant, acquiring side, card network, issuing bank and related service providers. The visible tap or click is only the start.',sections:[['Authorisation','The merchant side sends an authorisation request through the relevant route. The issuer or delegated decisioning system may approve or decline based on available information and rules.'],['Clearing and settlement','Transaction data is exchanged and obligations are calculated under the network’s rules. Settlement occurs according to the applicable arrangements. These stages are not the same as the initial approval.'],['Currency conversion','Conversion may occur at different points depending on the card, issuer, merchant currency and customer choices. Fees and exchange rates should be checked in the applicable terms.'],['Disputes','A refund, chargeback and payment reversal are not interchangeable. Their rules, eligibility and timing depend on the scheme and transaction type.']]},
  stablecoin:{category:'INNOVATION · DIGITAL ASSETS',title:'Stablecoins: what the name does and does not promise',lede:'A stablecoin is a digital token designed to maintain a value relative to a reference asset, often a currency. The design, issuer, backing, redemption and legal rights determine its actual risk.',sections:[['How a transfer may work','A user obtains tokens, sends them to a blockchain address, and the network records the token transfer. A recipient may hold the token, exchange it or redeem it if the relevant arrangements allow.'],['What still matters','Who issues the token? What backs it? Can holders redeem at par, under what terms and during what conditions? Who safeguards reserves? Which blockchain and intermediaries are involved? What happens during congestion, depegging or a freeze?'],['Potential advantages','Some designs may enable transfers at any time, programmable settlement or new integrations. Whether this improves cost, speed or access depends on the full route, on/off ramps, liquidity, compliance and local rules.'],['Limitations and risks','Reserve, issuer, redemption, market, technology, custody, operational, governance and legal risks can arise. A token designed to be stable is not guaranteed to remain stable or be accepted everywhere.'],['India and global context','Legal treatment and permitted activities vary by jurisdiction and change over time. Do not assume a token is equivalent to bank money, central bank money or a regulated deposit. Check current official rules.']]},
  authorisation:{category:'OPERATIONS',title:'Authorisation',lede:'Authorisation is a decision about whether a requested transaction or action is approved under the relevant system rules. It does not always mean that final settlement has occurred.',sections:[['Card context','An issuer or its delegated system may approve or decline a card authorisation request. An approval can reserve available credit or funds, depending on the product.'],['Other payment systems','The term and sequence differ by system. In an instant bank transfer, validation, authentication, account checks and the transfer of funds may be organised differently from a card transaction.'],['Why it matters','A customer-facing “approved” message should reflect the actual state defined by the system. It should not imply that all later processing, settlement or reconciliation has already completed.']]},
  clearing:{category:'OPERATIONS',title:'Clearing',lede:'Clearing is the process of transmitting, validating, matching or calculating payment obligations between participants, according to the rules of a particular system.',sections:[['Why it exists','A payment system needs an agreed way to determine which participant owes what to whom, and what data is required to support those obligations. Some systems process transactions individually; others use files, batches or netting.'],['Clearing is not settlement','Clearing determines or communicates obligations. Settlement discharges those obligations through the relevant accounts or settlement assets. The sequence and timing differ by system.'],['Examples vary','Card networks, batch payment systems and real-time systems have different operating models. Avoid assuming every payment passes through one generic clearing stage.']]},
  settlement:{category:'OPERATIONS',title:'Settlement',lede:'Settlement is the discharge of a payment obligation under the rules and arrangements of the relevant system. It is not simply the moment an app says “success”.',sections:[['What settles?','Depending on the arrangement, settlement may occur across accounts held at a central bank, commercial bank or another settlement institution, or through another legally defined arrangement.'],['Gross and net approaches','Gross settlement processes obligations individually. Net settlement offsets obligations before settling the net amounts. Systems can use different timing, liquidity and risk arrangements.'],['Why users may not see it','A merchant can receive an authorisation or confirmation before all settlement and reconciliation processes are complete. The exact meaning of status messages depends on the product and system rules.']]},
  pending:{category:'EXCEPTION HANDLING',title:'Pending is a state of uncertainty',lede:'When a response is missing or delayed, the system may not know whether the requested action completed. The absence of a response is not proof that the payment failed.',sections:[['Possible causes','Network latency, a downstream service outage, delayed processing, a lost response or a status-update issue. These are examples, not a diagnosis of a particular case.'],['Safer response','Check the authoritative status using the original transaction reference. Use the provider’s approved status enquiry or support process. Do not blindly create a new transaction while the outcome is uncertain.'],['Why idempotency matters','An idempotency key lets a service recognise retries of the same logical request. It can reduce duplicate processing when implemented correctly, but it does not replace status checks or provider-specific handling.'],['User communication','Explain what is known, what remains uncertain, what the customer should do and when to escalate. Do not call a transaction failed solely because a client timed out.']]},
  duplicate:{category:'EXCEPTION HANDLING',title:'Duplicate requests and idempotency',lede:'A duplicate request can happen when a user double-clicks, a client retries after a timeout or a network repeats a message. Systems need a deliberate way to handle repeats.',sections:[['Idempotency key','A unique key identifies one logical operation. When the same request is retried with the same key, a well-designed service can return the prior result rather than execute a second operation.'],['Limits','Key scope, expiry, payload consistency, concurrency and durable storage matter. An in-memory demo guard is not sufficient for a production payment service.'],['Related controls','Unique transaction references, request deduplication, authoritative status checks, audit logs and reconciliation help identify duplicate or inconsistent processing.']]},
  reversal:{category:'EXCEPTION HANDLING',title:'Refund, reversal and dispute are different',lede:'These terms are related but do not mean the same thing. The applicable definitions and processes depend on payment method, network rules, contract and law.',sections:[['Refund','A merchant or provider initiates a return of funds after a purchase or transaction, subject to the applicable process. Timing can differ from the original payment.'],['Reversal','A transaction or posting may be reversed or corrected under specific system rules, including when a transaction did not complete as expected. Not every correction is called a reversal.'],['Dispute / chargeback','A customer may dispute a transaction under a defined process. Card chargebacks have scheme-specific rules; bank transfer complaints follow different routes.'],['What to record','Original transaction reference, related adjustment reference, amount, currency, reason, status, timestamp and evidence, subject to privacy and retention rules.']]},
  eventlog:{category:'OPERATIONS · RECORDS',title:'Event log',lede:'An event log records what a system observed or did, often with timestamps and identifiers. It helps explain how the system reached a state.',sections:[['Useful event fields','Timestamp, event type, transaction identifier, source component, status, reason code and safe diagnostic context. Production logs should avoid exposing secrets or unnecessary personal data.'],['Auditability','A reliable trail helps operations investigate outages, disputes, fraud signals and data mismatches. Logging should be access-controlled and protected from tampering.'],['Limitations','A log is evidence of what that system recorded. It may be incomplete, delayed or wrong; it should be correlated with other trusted records when investigating.']]},
  data:{category:'ARCHITECTURE · DATA',title:'Data, analytics and reporting',lede:'Financial services use data for operations, risk, service, compliance and business decisions. Data quality, provenance, access and purpose are as important as the analytics itself.',sections:[['Common uses','Transaction monitoring, fraud patterns, credit assessment, service performance, reconciliation, customer support, product analytics and regulatory reporting.'],['Risks','Stale or incorrect data, biased samples, inappropriate access, weak consent, over-retention, model drift and unclear accountability.'],['Good practice','Define the purpose, source, quality checks, permissions, retention and ownership of important data. Explain when an output is an estimate or model score rather than a confirmed fact.']]},
  rbi:{category:'REGULATORY REFERENCE · INDIA',title:'Reserve Bank of India (RBI)',lede:'The RBI is India’s central bank and has regulatory and supervisory responsibilities across banking, payment systems and other areas within its legal remit.',sections:[['What it does','Its responsibilities include monetary policy, banking regulation and supervision, financial stability and oversight of payment and settlement systems under applicable laws. The exact authority depends on the activity.'],['What it does not mean','Not every fintech product is regulated in the same way or solely by the RBI. Securities, insurance, pensions, data protection and other activities can involve different authorities and laws.'],['How to use this reference','Read the current circular, regulation, directions or report that applies to the specific activity. Summaries help orientation but should not replace the legal text.'],['Official source','RBI annual reports and official website: rbi.org.in. Regulatory material changes; verify the current version and effective date.']]},
  npci:{category:'PAYMENT SYSTEM OPERATOR · INDIA',title:'National Payments Corporation of India (NPCI)',lede:'NPCI operates and develops major retail payment systems in India, including UPI. Its role as a system operator differs from the role of a statutory regulator.',sections:[['Why it matters','NPCI publishes product and ecosystem statistics, operating information and material about payment systems it operates. These sources help explain scale and system-specific behaviour.'],['UPI in context','UPI provides an interoperable framework for bank-account-based payments through participating applications and institutions. The user’s app, the payer/payee banks and the payment system have distinct roles.'],['Use statistics carefully','Check the month, definition, value/volume units and exclusions. An ecosystem statistic does not necessarily mean every participant has the same performance or experience.'],['Official sources','NPCI product statistics and official NPCI information are linked in References.']]},
  fatf:{category:'INTERNATIONAL STANDARDS',title:'Financial Action Task Force (FATF)',lede:'FATF develops international standards and promotes effective measures against money laundering, terrorist financing and proliferation financing.',sections:[['What it does','FATF Recommendations describe an international framework. Jurisdictions implement standards through their own laws, regulations, supervisors and enforcement arrangements.'],['What it does not do','FATF is not a global police force that directly authorises each customer payment, and its standards do not automatically replace local law. Obligations depend on the jurisdiction and regulated activity.'],['Why fintech teams care','Digital onboarding, cross-border transfers, virtual assets and new payment models raise questions about identity, transaction monitoring, beneficial ownership, record keeping and risk-based controls.'],['Official source','Read the current FATF Recommendations and related guidance; the version and effective status matter.']]},
  fsb:{category:'GLOBAL COORDINATION',title:'Financial Stability Board (FSB)',lede:'The FSB coordinates international work on financial stability and publishes policy reports, including the G20 roadmap for improving cross-border payments.',sections:[['Why it matters','Cross-border payment improvements require cooperation among public authorities, payment systems, banks, non-bank providers and market participants. One provider cannot solve every legal and infrastructure barrier alone.'],['Targets are not results','The G20 targets address cost, speed, access and transparency. For example, the target for retail cross-border payment costs is a global average of no more than 1%, with no corridor above 3%, by end-2027. These are policy targets, not proof of current corridor performance.'],['Official source','FSB cross-border payment targets and progress reports are linked in References.']]},
  innovationframework:{category:'INNOVATION · EVALUATION',title:'Evaluate an innovation without hype',lede:'Use the same questions for every new financial technology. This keeps the platform balanced and useful to future business leaders.',sections:[['1. Problem','What specific problem does it solve, and for whom? Is the problem important enough to justify the change?'],['2. Mechanism','How does it actually work? Which institutions, software, data, assets or networks are involved?'],['3. Evidence','What has been measured in real deployments? Separate pilots, projections, vendor claims and audited results.'],['4. Economics','Who pays, who saves, who captures value and what new costs appear? Include integration, compliance, operations and customer support.'],['5. Risks and accountability','What can fail? Who is responsible? What are the fraud, privacy, legal, cyber, concentration and consumer-protection risks?'],['6. Alternatives','Could the same problem be solved with a simpler existing system? Innovation should be compared against the real alternative, not against an imaginary perfect status quo.']]},
  openbanking:{category:'INNOVATION',title:'Open banking and data-sharing APIs',lede:'Open banking generally refers to structured, permissioned access to financial data or services through defined interfaces. Terminology, legal frameworks and capabilities differ across markets.',sections:[['How it works','A customer may authorise a third-party service to access specified account data through a controlled interface. The participating institutions, consent mechanism, authentication and data scope depend on the framework.'],['Potential benefits','More useful financial management, easier switching, account aggregation, tailored services and new business models. Benefits depend on user needs, quality and fair competition.'],['Risks and limitations','Consent that is hard to understand, excessive data access, credential theft, insecure integrations, unclear liability and uneven availability can undermine trust.'],['India and global perspective','India has its own account aggregator framework and related rules; other markets use different open-banking regimes. Do not assume one jurisdiction’s model applies globally. Verify current rules from official sources.']]},
  cbdc:{category:'INNOVATION',title:'Central bank digital currency (CBDC)',lede:'A CBDC is a digital form of central bank money. Its design and availability depend on the issuing central bank and jurisdiction.',sections:[['How it differs','Commercial bank deposits are claims on commercial banks. A CBDC is a liability of the central bank under its design. A privately issued stablecoin has a different issuer and risk structure.'],['Design questions','Retail or wholesale use, access model, privacy, offline capability, intermediaries, programmability, interoperability and impact on the financial system. Not every CBDC has the same design.'],['Potential benefits and challenges','CBDCs may offer new payment or settlement options. Adoption, user experience, privacy, resilience, operational costs and the effect on existing financial institutions require careful evaluation.'],['Evidence','Use central-bank publications for the status and design of a specific CBDC. Announcements, pilots and live public availability are distinct states.']]},
  embedded:{category:'INNOVATION',title:'Embedded finance',lede:'Embedded finance places a financial service inside a non-financial journey, such as offering payments, credit or insurance within a commerce or business application.',sections:[['Example','A small business platform may let a merchant accept payments, view cash flow and apply for a loan without moving to a separate banking interface. The underlying service may be supplied by a partner institution.'],['Why it can help','Less friction, more contextual services and integrated workflows. For a business, integration can reduce manual steps and improve visibility.'],['Risks','Customers may not know which company provides the financial product, who holds funds, who sets terms or who handles complaints. Credit offers can also create unsuitable borrowing or opaque pricing.'],['Design principle','Make the provider, price, terms, consent and complaint path clear at the point of decision. Integration should not obscure accountability.']]},
  'ai-finance':{category:'INNOVATION',title:'Artificial intelligence in finance',lede:'AI can support fraud detection, document processing, customer service, forecasting and decision support. It does not remove the need for accountable controls.',sections:[['Potential uses','Pattern detection across transactions, routing support, document extraction, service triage and analyst assistance. High-impact decisions need appropriate validation and oversight.'],['Failure modes','False positives, missed fraud, biased training data, model drift, fabricated explanations, privacy leakage, automation bias and lack of explainability.'],['Good governance','Define intended use, measure errors, monitor performance, protect data, provide escalation and appeal paths, and assign responsibility to people and institutions.'],['Transparency','A model score is not proof. A predicted risk is not a confirmed fact. Users should know when automation materially affects a financial decision where disclosure is required or appropriate.']]},
  tokenisation:{category:'INNOVATION',title:'Tokenisation',lede:'Tokenisation represents a claim, asset or right as a digital token under a defined technical and legal arrangement. The token alone does not guarantee that the underlying legal right is enforceable.',sections:[['What may be represented','A token might represent a financial instrument, claim, ownership interest or other asset, depending on the legal structure and system. Tokenisation is not limited to cryptocurrency.'],['Potential benefits','Programmable workflows, fractional access in some structures, faster coordination and new settlement models may be possible. Real benefits depend on standards, law, custody and market adoption.'],['Risks','Unclear ownership rights, custody failures, cyber risk, interoperability problems, liquidity gaps and mismatch between on-chain records and off-chain legal rights.'],['Key question','What exactly does the token holder legally own or have a claim to, and what happens if the issuer, platform or technology fails?']]},
  'ai-finance':{category:'INNOVATION',title:'Artificial intelligence in finance',lede:'AI can help detect patterns and automate selected tasks, but it does not remove the need for accountable decisions, validation and oversight.',sections:[['Where it is used','Examples include fraud detection, document processing, customer-service triage, forecasting, risk analysis and analyst support. The suitability of AI depends on the task and consequences of error.'],['Benefits','AI may help process large volumes of information, identify unusual patterns and reduce repetitive work when carefully implemented. Benefits must be measured against a realistic baseline.'],['Risks','False positives, missed fraud, biased data, model drift, privacy leakage, inaccurate generated content, weak explainability and over-reliance on automation.'],['Controls','Define intended use, test performance across relevant groups, monitor outcomes, protect data, provide human escalation where needed and assign clear accountability. A model score is not proof of wrongdoing.']]},
  digitalbanking:{category:'FINTECH PRODUCTS',title:'Digital banking',lede:'Digital banking uses digital channels and technology to deliver banking services, while the underlying institution and account systems remain essential.',sections:[['What users can do','Depending on the bank and jurisdiction, customers may check balances, transfer funds, manage cards, deposit cheques, apply for products or receive support through an app or browser.'],['Behind the interface','The channel connects to authentication, customer information, core banking, payment systems, fraud controls, notification services and records. Not every task is handled by one system.'],['Benefits and limitations','Digital channels can improve convenience and access, but depend on connectivity, accessibility, secure devices, reliable systems and support for customers who cannot use digital channels.']]},
  lending:{category:'FINTECH PRODUCTS',title:'Digital lending',lede:'Digital lending uses technology across applications, identity checks, underwriting, disbursement, servicing and repayment. A digital interface does not change the need for responsible credit decisions.',sections:[['Typical workflow','Application → identity and eligibility checks → income or cash-flow assessment → credit decision → offer and disclosures → agreement → disbursement → repayment servicing.'],['Where technology helps','Document extraction, workflow automation, alternative data where lawful, fraud controls, customer communication and repayment monitoring.'],['Risks and safeguards','Unsuitable credit, opaque pricing, poor data, discriminatory models, aggressive collection, privacy issues and unclear responsibility between a platform and lender. Clear disclosures and accountable lending practices matter.']]},
  insurtech:{category:'FINTECH PRODUCTS',title:'InsurTech: technology in insurance',lede:'InsurTech applies technology to insurance distribution, underwriting, policy servicing, claims and risk analysis.',sections:[['Example','A customer buys a policy online, submits evidence through an app and tracks a claim. The insurer still needs policy rules, risk assessment, fraud controls and claims decisions.'],['Potential benefits','Simpler onboarding, better workflow visibility, quicker document processing and more convenient service.'],['Trade-offs','Automated decisions can be wrong; data may be incomplete; customers may struggle to appeal; and a smooth interface cannot replace clear policy terms or fair claims handling.']]},
  wealthtech:{category:'FINTECH PRODUCTS',title:'WealthTech and investment platforms',lede:'WealthTech uses technology to support investing, portfolio visibility, financial planning and wealth-management services.',sections:[['Common functions','Account aggregation, portfolio views, investment execution, automated rebalancing, research tools and financial-planning interfaces. Features and permissions depend on the product and jurisdiction.'],['Important distinctions','An educational tool, an execution platform, an investment adviser and a broker may have different roles and regulatory obligations. An attractive dashboard is not evidence of investment quality.'],['Risks','Market risk remains. Users should understand fees, suitability, conflicts, data security, execution terms and the limits of automated recommendations.']]},
  regtech:{category:'FINTECH PRODUCTS',title:'RegTech: technology for compliance',lede:'Regulatory technology helps organisations manage compliance work, monitoring, reporting and evidence. It supports accountable teams rather than transferring responsibility away from them.',sections:[['Examples','Automated reporting workflows, policy tracking, identity checks, transaction monitoring, record retention and audit evidence.'],['Why it helps','Large institutions handle many rules, products and records. Well-designed tools can improve consistency and reduce manual effort.'],['Risks','Bad data, outdated rules, poor configuration, opaque alerts and automation bias can create compliance gaps. Rules and ownership must be maintained.']]},
  personalfinance:{category:'FINTECH PRODUCTS',title:'Personal finance tools',lede:'Personal finance technology helps people view spending, plan budgets, track goals or bring financial information together.',sections:[['Common functions','Expense categorisation, bill reminders, budgeting, cash-flow forecasts, savings goals and account aggregation where available.'],['Potential value','A clearer picture of cash flow can help users make informed choices and spot recurring costs.'],['Risks','Categorisation errors, insecure data sharing, misleading recommendations and unclear monetisation. A forecast is an estimate, not a guarantee.']]},
  'rbi':{category:'REGULATORY REFERENCE · INDIA',title:'Reserve Bank of India (RBI)',lede:'The RBI is India’s central bank and has regulatory and supervisory responsibilities across banking, payment systems and other areas within its legal remit.',sections:[['What it does','Its responsibilities include monetary policy, banking regulation and supervision, financial stability and oversight of payment and settlement systems under applicable laws. The exact authority depends on the activity.'],['What it does not mean','Not every fintech product is regulated in the same way or solely by the RBI. Securities, insurance, pensions, data protection and other activities can involve different authorities and laws.'],['How to use this reference','Read the current circular, regulation, directions or report that applies to the specific activity. Summaries help orientation but should not replace the legal text.']]}
};

const timelines = [
 ['Before the 1960s','Paper, branches and bookkeeping','Financial records were largely physical or manually maintained. Access depended heavily on location, staff and business hours.','Trust was built through institutions, procedures and records.'],
 ['1960s–1980s','Computers enter finance','Large institutions began automating calculations, account processing and high-value interbank operations.','Automation increased scale but created dependence on complex technology.'],
 ['1980s–2000s','Cards, ATMs and networks','Electronic cards, ATM networks, telephone banking and interbank systems expanded access beyond the branch.','Convenience grew while fraud controls and network resilience became more important.'],
 ['2000s–2010s','Internet and mobile banking','Web interfaces and smartphones moved more services into the customer’s hands. Institutions added digital channels around core systems.','The interface changed faster than many underlying systems.'],
 ['2010s–today','APIs, instant payments and data','Cloud services, APIs, mobile-first products, real-time payment systems and data-driven services connected more participants.','Interoperability and speed improved in some areas, while outages, cyber risk and data governance became central.'],
 ['Emerging / uneven','Programmable and tokenised finance','AI, tokenisation, stablecoins and CBDC experiments explore new ways to automate, represent or transfer value. Adoption varies widely.','A pilot, proposal or market narrative is not the same as proven scale or universal usefulness.']
];
$('#timeline').innerHTML = timelines.map((t,i)=>`<div class="timeline-item"><div class="timeline-dot"></div><button type="button" data-detail="timeline-${i}"><span class="year">${escapeHtml(t[0])}</span><h3>${escapeHtml(t[1])}</h3><p>${escapeHtml(t[2])}</p><small>Explore the shift ↗</small></button></div>`).join('');
// Reveal the evolution timeline gently as it enters view; respect reduced-motion settings.
(function animateTimeline(){const items=$$('#timeline .timeline-item');if(!items.length)return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){items.forEach(el=>el.classList.add('is-visible'));return;}if(!('IntersectionObserver' in window)){items.forEach(el=>el.classList.add('is-visible'));return;}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}}),{threshold:.14});items.forEach((el,i)=>{el.style.setProperty('--reveal-order',i);observer.observe(el);});})();
timelines.forEach((t,i)=>{detailData[`timeline-${i}`]={category:'FINTECH EVOLUTION',title:t[1],lede:t[2],sections:[['Why it mattered',t[3]],['What to keep in mind','This is a simplified timeline, not a claim that every country or institution followed the same sequence. Technologies overlapped, adoption differed and legacy systems continued to operate alongside newer services.']]};});

const terms = [
['API','Technology','Application Programming Interface. A defined way for software systems to request information or actions from one another.','A finance app requests account information through an authorised API; the API is the interface, not the bank or payment rail.','api'],
['Authentication','Risk & regulation','Checking evidence that a user, device or service is who or what it claims to be.','A service checks a login credential or another approved factor before allowing access.','security'],
['Authorisation','Payments','A decision that a requested transaction or action is approved under the relevant rules.','A card issuer may approve a purchase; this does not by itself mean all later settlement is complete.','authorisation'],
['AML','Risk & regulation','Anti-money laundering: controls and obligations intended to prevent and detect money laundering.','A regulated entity may monitor transactions for patterns requiring review, subject to applicable rules.','fatf'],
['KYC','Risk & regulation','Know Your Customer: processes to establish and verify customer identity and understand relevant risk.','A provider may request identity information before opening an account, where required.','rbi'],
['UPI','Payments','Unified Payments Interface, an Indian retail payment system operated by NPCI that supports interoperable bank-account payments.','A customer uses a participating app to pay a merchant; the app, banks and system have distinct roles.','network'],
['IMPS','Payments','Immediate Payment Service, an Indian interbank electronic funds transfer service.','It supports eligible transfers under its operating rules; check current participant and channel conditions.','network'],
['NEFT','Payments','National Electronic Funds Transfer, an RBI-operated Indian funds transfer system that processes transfers in batches at frequent intervals.','It is a bank transfer system with its own processing and settlement arrangements, not a card network.','network'],
['RTGS','Payments','Real Time Gross Settlement: transactions are settled individually in real time under the relevant system rules.','India’s RTGS is used for qualifying transfers and differs from batch-based mechanisms.','settlement'],
['Payment rail','Payments','The infrastructure and rules through which payment instructions or value transfers are processed.','UPI, card networks and bank transfer systems are different rails or system types with different rules.','network'],
['Payment gateway','Payments','A service that helps securely transmit payment information between a merchant interface and payment processing participants.','An online store may use a gateway to pass a card payment request into the relevant processing route.','cardcross'],
['Payment processor','Payments','A provider that performs operational functions for payment transactions, depending on its service and contract.','A processor may route transaction data, support authorisation or provide reporting; roles vary by arrangement.','provider'],
['Issuer','Payments','In card payments, the institution that issues the payment card or account relationship to the cardholder.','The issuer or its delegated system may make an authorisation decision.','cardcross'],
['Acquirer','Payments','In card payments, the institution or provider that enables a merchant to accept card transactions and processes them on the merchant side.','The acquirer connects the merchant to relevant card payment arrangements.','cardcross'],
['Clearing','Operations','The process of transmitting, validating, matching or calculating payment obligations under a system’s rules.','Card transaction data may be cleared before settlement according to the network’s process.','clearing'],
['Settlement','Operations','The discharge of a payment obligation under the relevant system and legal arrangements.','A payment’s approval message and the settlement of obligations are not always the same event.','settlement'],
['Reconciliation','Operations','Comparing records from different sources to identify matches and exceptions.','A merchant compares order records with provider reports and internal ledger entries.','reconciliation'],
['Ledger','Operations','A structured record of financial positions or movements.','A ledger entry records a financial event; an event log records what the software observed.','ledger'],
['Event log','Operations','A timestamped record of system events and state changes.','A log may record request received, check completed, timeout or record posted.','eventlog'],
['Idempotency','Technology','A property that allows repeated requests for the same logical operation to avoid duplicate execution when correctly implemented.','A retry with the same idempotency key can return the prior result instead of creating a second payment.','duplicate'],
['Webhook','Technology','A mechanism by which one service sends an event notification to another service, often over HTTP.','A provider may notify a merchant that a payment status changed; the merchant should verify and safely process events.','api'],
['OAuth','Technology','An authorisation framework used to grant limited access to resources without sharing a user’s password with every application.','A third-party app may receive a scoped access token under a supported consent flow.','security'],
['Core banking','Technology','Software and systems supporting essential bank operations such as accounts, balances and transaction posting.','A mobile banking app may call services that ultimately depend on core banking records.','corebanking'],
['Open banking','Innovation','A framework or market practice for permissioned sharing of financial data or services through defined interfaces.','An account aggregation service may access selected data under a customer-authorised arrangement.','openbanking'],
['Embedded finance','Innovation','Financial services integrated into a non-financial product or workflow.','A business software platform may offer payments or a loan application within its own interface.','embedded'],
['Stablecoin','Innovation','A digital token designed to maintain value relative to a reference asset; its risks depend on issuer, reserves, redemption and design.','A token may aim to track a currency, but its price and redemption are not guaranteed in every circumstance.','stablecoin'],
['CBDC','Innovation','Central Bank Digital Currency: a digital form of central bank money, under the design of the issuing central bank.','A retail CBDC concept differs from commercial bank deposits and privately issued stablecoins.','cbdc'],
['Tokenisation','Innovation','Representing a claim, asset or right as a digital token under a particular technical and legal arrangement.','A tokenised asset still depends on enforceable rights, custody and the system that recognises ownership.','tokenisation'],
['FX','Global payments','Foreign exchange: converting one currency into another at an exchange rate.','A cross-border transfer may convert the sender’s currency to the recipient’s currency, with fees or a margin.','crossborder'],
['Correspondent banking','Global payments','Banking relationships through which one bank provides services or access to another bank, often across currencies or markets.','A bank may use a correspondent to reach a foreign payment system or settle in a currency.','correspondent'],
['Remittance','Global payments','A transfer of money, often sent by a person living or working abroad to a recipient elsewhere.','A worker sends money to family through a bank or authorised money transfer provider.','remittance'],
['SWIFT','Global payments','A financial messaging network used by financial institutions to exchange standardised financial messages; it is not itself the settlement of funds.','A message can carry payment instructions while settlement occurs through relevant accounts and arrangements.','correspondent'],
['ISO 20022','Global payments','An international standard for financial messaging with structured data models.','A payment message can carry more structured information, subject to implementation and market rules.','iso'],
['Sanctions screening','Risk & regulation','Checking parties or transactions against relevant sanctions restrictions and lists, as required by applicable law and policy.','A potential name match may require investigation; a screening alert is not automatically a confirmed match.','fatf'],
['Fraud detection','Risk & regulation','Methods to identify suspicious or unauthorised activity using rules, signals, models or investigation.','A velocity rule may flag repeated high-frequency transactions for review.','controls'],
['False positive','Risk & regulation','A system flags legitimate activity as suspicious or disallowed.','A genuine customer’s transaction may be held after an unusual travel or spending pattern.','controls'],
['Pending transaction','Payments','A status indicating the outcome or processing state is not yet definitively known or completed, depending on the system.','A timeout may leave a transaction pending until authoritative status is checked.','pending'],
['Reversal','Operations','A correction or undoing of a transaction or posting under the relevant system rules.','A reversal has a different trigger and process from a customer-initiated refund.','reversal'],
['Chargeback','Payments','A card-scheme dispute process through which a card transaction may be challenged under specific rules.','A cardholder may dispute an eligible transaction; timing and evidence requirements are scheme-specific.','cardcross'],
['API gateway','Technology','A component that manages API traffic and may apply routing, authentication, rate limits and monitoring.','An API gateway can enforce consistent controls before requests reach downstream services.','api'],
['Cloud computing','Technology','On-demand access to computing, storage and managed services over a network.','A fintech may use cloud infrastructure for analytics or services, while still needing resilience and security controls.','data'],
['Data minimisation','Risk & regulation','Collecting and processing only the personal data necessary for a defined purpose, subject to applicable law.','A service should not collect sensitive fields without a clear purpose and lawful basis.','security'],
['Credit scoring','Products','A method of estimating credit risk or repayment likelihood from relevant information and a model or rules.','A lender may use a score as one input to a decision; data quality, fairness and explainability matter.','provider'],
['RegTech','Innovation','Technology that supports regulatory compliance, reporting, monitoring or related controls.','A system may help track policy changes or prepare reports, but accountability remains with the responsible organisation.','rbi'],
['InsurTech','Products','Technology applied to insurance distribution, underwriting, servicing, claims or risk assessment.','A digital claims workflow may automate document intake while retaining review for complex cases.','embedded'],
['WealthTech','Products','Technology used for investing, portfolio management, financial advice or wealth services.','An app may help users view holdings or execute investment instructions under applicable regulation.','sebi'],
['Financial inclusion','Products','Expanding meaningful access to useful and affordable financial services, especially for underserved groups.','Digital services may reduce some access barriers but can introduce new barriers around connectivity, literacy, identity or accessibility.','worldbankGov'],
['Net settlement','Operations','Settlement of netted obligations after offsetting amounts owed between participants.','Instead of settling each gross obligation separately, a system may settle the net position under its rules.','settlement'],
['Liquidity risk','Risk & regulation','The risk that an institution cannot meet payment obligations when due, even if it may be solvent overall.','Settlement timing and liquidity arrangements can affect a participant’s ability to pay on time.','settlement'],
['Data residency','Risk & regulation','Rules or arrangements concerning where data is stored or processed.','A provider may need to account for local legal and contractual requirements when processing financial data.','data'],
['API timeout','Technology','A request does not receive a response within the expected time limit.','The caller may not know whether the downstream operation completed; check status before retrying.','pending'],
['Payment orchestration','Technology','Coordinating multiple payment providers, routes, rules and retries through a defined layer.','A merchant may route transactions based on availability, cost or acceptance, with controls to prevent duplicates.','provider'],
['Interoperability','Technology','The ability of systems to work together and exchange or interpret information under agreed standards and rules.','Interoperable payment systems can let users of different participating providers transact, subject to system rules.','network'],
['Merchant category code (MCC)','Payments','A code used in card payments to classify the type of merchant.','A merchant category may affect reporting or certain transaction rules; assignment and use depend on scheme processes.','cardcross']
];
const glossary = terms.map(([term,category,definition,example,detail])=>({term,category,definition,example,detail}));
function renderGlossary(){const query=($('#glossary-search').value||'').trim().toLowerCase();const list=glossary.filter(t=>(state.glossaryFilter==='All'||t.category===state.glossaryFilter)&&`${t.term} ${t.category} ${t.definition} ${t.example}`.toLowerCase().includes(query));$('#glossary-count').textContent=`${list.length} ${list.length===1?'term':'terms'} · ${glossary.length} in dictionary`;$('#glossary-grid').innerHTML=list.map(t=>`<button class="term-card" data-term="${escapeHtml(t.term)}"><span>${escapeHtml(t.category.toUpperCase())}</span><h3>${escapeHtml(t.term)}</h3><p>${escapeHtml(t.definition)}</p><b>Read definition & example ↗</b></button>`).join('');$('#glossary-empty').classList.toggle('hidden',list.length>0);}
renderGlossary();

