 ['INDIA · PAYMENT SYSTEM','NPCI UPI product statistics','Monthly and annual UPI volumes, values and participating-bank information. Check the period and definition on the page.',sourceLinks.npci.url,'Official operator'],
 ['INDIA · POLICY & DATA','Government of India · digital payments','Government releases on digital payment adoption and UPI scale, including stated reporting periods.',sourceLinks.govtUppi.url,'Official government source'],
 ['INDIA · CENTRAL BANK','Reserve Bank of India','Annual reports, payment system policy, regulations, supervision and financial stability publications.',sourceLinks.rbi.url,'Official regulator'],
 ['GLOBAL · PAYMENTS','Bank for International Settlements','Cross-border payment programme, payment infrastructure, settlement and financial innovation research.',sourceLinks.bis.url,'International institution'],
 ['GLOBAL · POLICY TARGETS','Financial Stability Board','G20 cross-border payment targets and progress reporting across cost, speed, access and transparency.',sourceLinks.fsb.url,'Policy coordination'],
 ['GLOBAL · AML STANDARDS','FATF Recommendations','International AML/CFT standards and related guidance. Domestic law and implementation still matter.',sourceLinks.fatf.url,'International standard setter'],
 ['GLOBAL · MESSAGING','SWIFT','Information about financial messaging infrastructure. Messaging is not the same as settlement of funds.',sourceLinks.swift.url,'Network information'],
 ['GLOBAL · REMITTANCE COSTS','World Bank · Remittance Prices Worldwide','Data on remittance costs across corridors. Compare like-for-like services and note the collection date.',sourceLinks.worldbank.url,'Research database'],
 ['GLOBAL · MESSAGING STANDARDS','ISO 20022','Structured financial messaging standard and implementation resources.',sourceLinks.iso.url,'Standards body'],
 ['GLOBAL · DIGITAL FINANCE','International Monetary Fund · Fintech','Research and policy resources on fintech, digital money and financial stability.',sourceLinks.imf.url,'International institution'],
 ['INDIA · DIGITAL ID','UIDAI','Official information on Aadhaar and authentication; the applicability of rules depends on context.',sourceLinks.uidai.url,'Official authority'],
 ['INDIA · SECURITIES','SEBI','Securities market regulation, investor information and official circulars.',sourceLinks.sebi.url,'Official regulator'],
 ['INDIA · INSURANCE','IRDAI','Insurance-sector regulation and official consumer resources.',sourceLinks.irdai.url,'Official regulator'],
 ['GLOBAL · INCLUSION','World Bank · Global Findex','Research on financial inclusion and access to financial services across economies.',sourceLinks.worldbankGov.url,'Research database']
