$('#sources-grid').innerHTML=sourceCards.map(s=>`<a class="source-card" href="${s[3]}" target="_blank" rel="noopener"><span class="source-tag">${escapeHtml(s[0])}</span><h3>${escapeHtml(s[1])}</h3><p>${escapeHtml(s[2])}</p><b>${escapeHtml(s[4])} ↗</b></a>`).join('');

