function openPage(page){if(!$(`#page-${page}`))return;$$('.page').forEach(p=>p.classList.toggle('active',p.dataset.page===page));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));state.currentPage=page;window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});if(page==='glossary')$('#glossary-search').focus({preventScroll:true});}
