// Payment simulator
function nextId(){return `FT-${new Date().toISOString().slice(2,10).replaceAll('-','')}-${String(state.counter++).padStart(4,'0')}`;}
function renderMetrics(){$('#metric-total').textContent=state.transactions.length;$('#metric-success').textContent=state.transactions.filter(t=>t.status===STATUSES.SUCCESS).length;$('#metric-attention').textContent=state.transactions.filter(t=>t.status!==STATUSES.SUCCESS).length;$('#metric-recon').textContent=state.lastRecon?(state.lastRecon.matched?'Matched':'Exceptions'):'Not run';}
function renderRows(){const filter=$('#filter-status').value;const rows=state.transactions.filter(t=>filter==='ALL'||t.status===filter).slice().reverse();$('#transaction-rows').innerHTML=rows.length?rows.map(t=>{const [label,klass]=statusMeta[t.status];return `<tr data-id="${escapeHtml(t.id)}" class="${t.id===state.selectedId?'selected':''}"><td><span class="tx-id">${escapeHtml(t.id)}</span></td><td>${escapeHtml(t.merchant)}</td><td>${fmtMoney(t.amount)}</td><td>${escapeHtml(t.rail.replaceAll('_',' '))}</td><td><span class="status-badge ${klass}">${label}</span></td><td>${fmtTime(t.createdAt)}</td><td><button class="row-action" data-inspect="${escapeHtml(t.id)}" type="button">Inspect ↗</button></td></tr>`;}).join(''):'<tr><td colspan="7" class="empty-table">No transactions match this view.</td></tr>';}
const stageCopy={initiated:['Initiate','A customer or business creates a payment instruction. The system needs enough information to identify the amount, destination and requested method.'],validated:['Validate','The request is checked for required fields, amount limits and basic format. Production systems also apply security and product-specific controls.'],authorised:['Decision','A simulated decision is returned. The exact authorisation path differs by payment method; this model uses a simplified common teaching sequence.'],recorded:['Record','The simulation writes fictional internal and settlement records for a successful outcome. Real systems have system-specific clearing, settlement and recordkeeping rules.']};
function activeStageFor(tx){if(!tx)return 'initiated';if(tx.status===STATUSES.VALIDATION_FAILED)return 'validated';if([STATUSES.DECLINED,STATUSES.PENDING_REVIEW].includes(tx.status))return 'authorised';return 'recorded';}
function explainStage(stage,tx){const [title,body]=stageCopy[stage];$('#stage-explanation').innerHTML=`<span class="explain-count">STAGE ${['initiated','validated','authorised','recorded'].indexOf(stage)+1<10?'0':''}${['initiated','validated','authorised','recorded'].indexOf(stage)+1}</span><h3>${title}</h3><p>${escapeHtml(body)}${tx?` Selected outcome: ${statusMeta[tx.status][0].toLowerCase()}.`:''}</p>`;}
function renderTrace(animate=false){const tx=state.transactions.find(t=>t.id===state.selectedId);const stages=['initiated','validated','authorised','recorded'];const final=activeStageFor(tx);let finalIndex=stages.indexOf(final);if(!tx)finalIndex=0;const els=$$('.trace-stage');if(state.traceTimer)clearInterval(state.traceTimer);if(animate&&tx){let i=0;const activate=()=>{els.forEach((el,n)=>{el.classList.toggle('active',n<=i);el.classList.toggle('done',n<i);el.classList.toggle('current',n===i);el.classList.toggle('failed',Boolean(tx)&&n===finalIndex&&tx.status!==STATUSES.SUCCESS);});$$('.trace-connector').forEach((el,n)=>{el.classList.toggle('active',n<i);});explainStage(stages[Math.min(i,finalIndex)],tx);if(i>=finalIndex){clearInterval(state.traceTimer);state.traceTimer=null;}else i++;};i=0;activate();state.traceTimer=setInterval(activate,680);}else{els.forEach((el,n)=>{el.classList.toggle('active',Boolean(tx)&&n<=finalIndex);el.classList.toggle('done',Boolean(tx)&&n<finalIndex);el.classList.toggle('current',Boolean(tx)&&n===finalIndex);el.classList.toggle('failed',Boolean(tx)&&n===finalIndex&&tx.status!==STATUSES.SUCCESS);});$$('.trace-connector').forEach((el,n)=>el.classList.toggle('active',Boolean(tx)&&n<finalIndex));explainStage(final,tx);}
if(!tx){$('#trace-title').textContent='From request to record';$('#trace-status').textContent='Ready';$('#trace-status').className='status-badge neutral';$('#event-count').textContent='0 events';$('#event-list').innerHTML='<li class="empty-state">Run a simulation to see timestamped events and the reason behind the outcome.</li>';return;}
const [label,klass]=statusMeta[tx.status];$('#trace-title').textContent=`${tx.id} · ${tx.rail.replaceAll('_',' ')}`;$('#trace-status').textContent=label;$('#trace-status').className=`status-badge ${klass}`;$('#event-count').textContent=`${tx.events.length} ${tx.events.length===1?'event':'events'}`;$('#event-list').innerHTML=tx.events.map(e=>`<li><span class="event-time">${fmtTime(e.at)}</span><span class="event-text"><strong>${escapeHtml(e.message)}</strong><small>${escapeHtml(e.detail)}</small></span></li>`).join('');}
function renderAll(animate=false){renderMetrics();renderRows();renderTrace(animate);}
$('#payment-form').addEventListener('submit',e=>{e.preventDefault();const merchant=$('#merchant').value.trim();const amount=Number($('#amount').value);const rail=$('#method').value;const scenario=$('#scenario').value;const requestKey=`REQ-${globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`}`;const result=createPayment({id:nextId(),merchant,amount,rail,scenario,requestKey},state.usedKeys);if(!result.ok){$('#form-message').textContent=result.errors.join(' ');return;}state.usedKeys.add(requestKey);state.transactions.push(result.transaction);state.selectedId=result.transaction.id;state.lastRecon=null;$('#form-message').textContent=`${result.transaction.id} created: ${statusMeta[result.transaction.status][0].toLowerCase()}. Follow the highlighted stages and event trail.`;renderAll(true);renderRecon(null);});
function loadExamples(){const examples=[{merchant:'Northstar Books',amount:1250,rail:'UPI',scenario:'success'},{merchant:'Cedar Foods',amount:849.5,rail:'CARD',scenario:'declined'},{merchant:'Meridian Supplies',amount:12500,rail:'BANK_TRANSFER',scenario:'timeout'},{merchant:'Harbour Studio',amount:2200,rail:'WALLET',scenario:'success'},{merchant:'Orchid Market',amount:2200,rail:'UPI',scenario:'invalid'}];for(const ex of examples){const requestKey=`REQ-${Date.now()}-${Math.random().toString(36).slice(2)}`;const result=createPayment({...ex,id:nextId(),requestKey},state.usedKeys);if(result.ok){state.usedKeys.add(requestKey);state.transactions.push(result.transaction);}}state.selectedId=state.transactions.at(-1)?.id||null;state.lastRecon=null;$('#form-message').textContent='Example cases loaded. Select any transaction to inspect its outcome.';renderAll(true);renderRecon(null);}
$('#seed-button').addEventListener('click',loadExamples);$('#filter-status').addEventListener('change',renderRows);$('#transaction-rows').addEventListener('click',e=>{const btn=e.target.closest('[data-inspect]');const row=e.target.closest('tr[data-id]');const id=btn?.dataset.inspect||row?.dataset.id;if(id){state.selectedId=id;renderRows();renderTrace(true);}});
function renderRecon(result){const box=$('#recon-results');if(!result){box.innerHTML='<div class="recon-empty">Run the check after creating transactions. A clean match is useful; an exception is a reason to investigate, not a diagnosis by itself.</div>';return;}box.innerHTML=`<div class="recon-status">${result.matched?'✓ Internal records match the simulated settlement records.':'⚠ Reconciliation found exceptions to investigate.'}</div><div class="recon-summary"><div class="recon-stat"><span>Successful records</span><strong>${result.transactionCount}</strong></div><div class="recon-stat"><span>Ledger total</span><strong>${fmtMoney(result.ledgerTotal)}</strong></div><div class="recon-stat"><span>Settlement total</span><strong>${fmtMoney(result.settlementTotal)}</strong></div></div>${result.exceptions.length?`<ul>${result.exceptions.map(x=>`<li>${escapeHtml(x.transactionId)}: ${escapeHtml(x.reason)}</li>`).join('')}</ul>`:''}<p class="table-note">Checked ${fmtTime(result.checkedAt)}. Fictional session data only.</p>`;}
$('#reconcile-button').addEventListener('click',()=>{state.lastRecon=reconcile(state.transactions);renderMetrics();renderRecon(state.lastRecon);});
$('#export-csv').addEventListener('click',()=>{if(!state.transactions.length){toast('Create or load transactions before exporting.');return;}const rows=[['Transaction ID','Merchant','Amount','Currency','Rail','Status','Created at','Request key'],...state.transactions.map(t=>[t.id,t.merchant,t.amount,t.currency,t.rail,t.status,t.createdAt,t.requestKey])];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='fintech-systems-lab-transactions.csv';a.click();URL.revokeObjectURL(url);toast('CSV export prepared.');});

// Risk scenario lab
const riskScenarios={normal:{class:'status-clear',icon:'✓',status:'Lower concern in this example',signal:'The transaction matches the expected pattern in the simplified model.',action:'Allow or continue with standard controls, subject to the product’s rules.',tradeoff:'A low-risk score is not a guarantee. Monitoring and basic safeguards still matter.'},velocity:{class:'status-warning',icon:'!',status:'Unusual transaction velocity',signal:'Several transactions arrive in a short period, which may be legitimate or suspicious.',action:'Apply a policy-based limit, step-up authentication or manual review if warranted.',tradeoff:'A strict rule can interrupt legitimate activity; a weak rule can miss abuse.'},mismatch:{class:'status-warning',icon:'!',status:'Identity or device mismatch',signal:'A device or identity signal differs from the established pattern.',action:'Request additional verification or route to review based on risk and policy.',tradeoff:'Signals can be noisy. Avoid treating a mismatch alone as proof of fraud.'},sanctions:{class:'status-danger',icon:'×',status:'Potential sanctions-screening match',signal:'A name or party identifier appears similar to a relevant screening record.',action:'Follow the applicable legal process, resolve false matches and escalate when required. Do not automatically infer guilt from a possible match.',tradeoff:'False positives can delay legitimate payments; missed true matches can breach legal obligations.'},account:{class:'status-danger',icon:'!',status:'Possible account takeover',signal:'The example combines a new device with unusual access or transaction behaviour.',action:'Protect the account, require appropriate verification, investigate and communicate a safe recovery path.',tradeoff:'A protective hold can frustrate a real customer, but ignoring a credible signal can cause loss.'}};
$('#run-risk').addEventListener('click',()=>{const r=riskScenarios[$('#risk-scenario').value];$('#risk-output').innerHTML=`<div class="risk-status ${r.class}"><span class="risk-status-icon">${r.icon}</span><div><span class="eyebrow">ILLUSTRATIVE CONTROL RESPONSE</span><h3>${escapeHtml(r.status)}</h3><p>${escapeHtml(r.signal)}</p></div></div><div class="risk-detail-grid"><div><b>Signal</b><p>${escapeHtml(r.signal)}</p></div><div><b>Possible action</b><p>${escapeHtml(r.action)}</p></div><div><b>Trade-off</b><p>${escapeHtml(r.tradeoff)}</p></div></div><div class="detail-callout"><b>Learning note</b><p>This is a fictional scenario. Real decisions depend on the applicable law, institution’s policy, data quality and investigation process.</p></div>`;});

// FX illustrative calculator: uses the user-entered rate directly and makes currency context explicit.
const currencySymbols={USD:'$',GBP:'£',EUR:'€',AED:'د.إ',SGD:'S$',INR:'₹'};
function calcFx(){const amount=Math.max(0,Number($('#fx-amount').value)||0);const rate=Math.max(0,Number($('#fx-rate').value)||0);const fee=Math.max(0,Number($('#fx-fee').value)||0);const margin=Math.min(100,Math.max(0,Number($('#fx-margin').value)||0))/100;const send=$('#fx-send').value;const receive=$('#fx-receive').value;const afterFee=Math.max(0,amount-fee);const effective=rate*(1-margin);const out=afterFee*effective;const symbol=currencySymbols[receive]||receive+' ';$('#fx-result').textContent=`${symbol}${out.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})} ${receive}`;$('#fx-breakdown').innerHTML=`Amount entered: ${amount.toLocaleString('en-IN',{maximumFractionDigits:2})} ${send}<br>Provider fee: ${fee.toLocaleString('en-IN',{maximumFractionDigits:2})} ${send}<br>Rate after example margin: ${effective.toFixed(4)} ${receive} per ${send}<br>Recipient estimate: ${out.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})} ${receive}`;}
['fx-amount','fx-rate','fx-fee','fx-margin','fx-send','fx-receive'].forEach(id=>$('#'+id).addEventListener('input',calcFx));$('#fx-send').addEventListener('change',()=>{const send=$('#fx-send').value;const receive=$('#fx-receive').value;const illustrative={USD:{INR:83,EUR:.92,GBP:.79,USD:1},GBP:{INR:105,USD:1.27,EUR:1.17,GBP:1},EUR:{INR:90,USD:1.09,GBP:.85,EUR:1},AED:{INR:22.6,USD:.272,EUR:.25,GBP:.215},SGD:{INR:61.5,USD:.74,EUR:.68,GBP:.58}};$('#fx-rate').value=illustrative[send]?.[receive]??1;calcFx();});$('#fx-receive').addEventListener('change',()=>{const send=$('#fx-send').value;const receive=$('#fx-receive').value;const illustrative={USD:{INR:83,EUR:.92,GBP:.79,USD:1},GBP:{INR:105,USD:1.27,EUR:1.17,GBP:1},EUR:{INR:90,USD:1.09,GBP:.85,EUR:1},AED:{INR:22.6,USD:.272,EUR:.25,GBP:.215},SGD:{INR:61.5,USD:.74,EUR:.68,GBP:.58}};$('#fx-rate').value=illustrative[send]?.[receive]??1;calcFx();});calcFx();

