// Interactive Playground: short decision missions across the financial technology lifecycle.
(function initArena(){
 const missions={
  payment:{level:'MISSION 01 · OPERATIONS',title:'The payment went quiet.',brief:'A customer paid ₹1,250. The app timed out, but the payment network has not confirmed the final status.',visual:'PAYMENT TRACE',question:'What should the system do next?',hint:'A timeout is not proof of failure. Choose the safest next step.',nodes:[['₹','Customer','₹1,250'],['▣','App','Request sent'],['↗','Network','Response delayed'],['▤','Bank record','Not confirmed']],events:['13:42:08 · Payment request accepted by app','13:42:09 · Network response not received in time','13:42:09 · Final outcome remains unknown'],takeTitle:'Unknown is a valid status.',take:'Well-designed payment systems distinguish a failed request from a request whose final outcome is not yet known.',choices:[['retry','Immediately send the payment again','Try to complete it faster','A duplicate payment may occur. The first request could already have succeeded even though its response was delayed.'],['check','Check status using the original reference','Confirm the outcome before acting','Strong decision. Query the original reference, reconcile the response and only retry when the system can safely establish that the first request did not complete.'],['fail','Tell the customer it definitely failed','Close the request now','This gives false certainty. The customer may pay again while the first transaction is still processing.']],best:'check'},
  fraud:{level:'MISSION 02 · TRUST & RISK',title:'A transaction looks unusual.',brief:'A fictional account makes four high-value attempts in two minutes from a new device. The customer has not yet confirmed the activity.',visual:'RISK SIGNAL MAP',question:'Which response balances safety and fairness?',hint:'A risk signal is evidence for a decision, not proof on its own.',nodes:[['ID','Identity','New device'],['↗','Velocity','4 attempts'],['◇','Control','Review needed'],['✓','Customer','Not confirmed']],events:['09:16:21 · New device detected','09:16:22 · Transaction velocity threshold crossed','09:16:22 · Customer confirmation not yet received'],takeTitle:'Risk controls need proportion.',take:'A proportionate response can add verification or hold a risky transaction while reducing unnecessary harm to genuine customers.',choices:[['allow','Approve every attempt','Avoid customer friction','This ignores multiple risk signals. A rapid series of high-value attempts from a new device deserves further checks.'],['block','Permanently block the account immediately','Stop all activity','This may protect the account, but the evidence may not justify a permanent action. Strong controls also need review and recovery paths.'],['verify','Pause and request step-up verification','Check before authorising','Strong decision. Apply a proportionate check, assess the response and escalate or hold if uncertainty remains. Keep a route for genuine customers to recover access.']],best:'verify'},
  recon:{level:'MISSION 03 · OPERATIONS',title:'The records do not agree.',brief:'The merchant system records ₹2,450. The payment provider record shows ₹2,450, but the internal ledger contains two entries for the same reference.',visual:'RECONCILIATION VIEW',question:'What is the right next action?',hint:'Do not change records just to make the totals match. Investigate the evidence.',nodes:[['₹','Merchant','₹2,450'],['↔','Provider','₹2,450'],['×2','Ledger','Duplicate entry'],['!','Reconcile','Exception']],events:['18:04:02 · Merchant record matched','18:04:03 · Provider reference matched','18:04:03 · Duplicate ledger entry detected'],takeTitle:'A mismatch is a signal to investigate.',take:'Reconciliation compares records and surfaces exceptions. The fix should preserve an audit trail and correct the underlying cause.',choices:[['delete','Delete one entry without checking','Make the total match','A blind deletion can remove a valid accounting record and destroy the audit trail. Confirm the duplicate and follow the correction procedure.'],['investigate','Compare reference, timestamps and event history','Verify the duplicate first','Strong decision. Confirm both entries refer to the same event, preserve evidence, correct through an auditable process and check the root cause.'],['ignore','Ignore it because the amounts match','Close the daily check','Equal amounts do not prove the records are correct. A duplicate can overstate balances or distort reporting.']],best:'investigate'},
  global:{level:'MISSION 04 · CROSS-BORDER PAYMENTS',title:'Choose the better transfer route.',brief:'A business needs to send the equivalent of ₹50,000 abroad. Route A is cheaper but slower; Route B costs more and offers a clearer delivery estimate.',visual:'CROSS-BORDER ROUTE',question:'What should you compare before choosing?',hint:'The best route depends on the business need, not one headline number.',nodes:[['₹','Sender','₹50,000'],['FX','Conversion','Rate + margin'],['⇢','Route','Cost / speed'],['◎','Recipient','Amount received']],events:['QUOTE A · Lower fee · Longer estimate','QUOTE B · Higher fee · Clearer estimate','DECISION · Compare total cost and delivery needs'],takeTitle:'Compare the whole outcome.',take:'A meaningful comparison includes the total cost, exchange-rate margin, recipient amount, delivery estimate, transparency and the importance of timing.',choices:[['cheapest','Choose the lowest visible fee','Optimise the headline charge','A low stated fee can hide a worse exchange rate or intermediary charges. Compare the final recipient amount and total cost.'],['fastest','Choose the fastest estimate automatically','Prioritise speed alone','Speed matters, but paying more may not be justified if timing is flexible. Compare the total cost against the actual business need.'],['compare','Compare recipient amount, total cost and delivery confidence','Choose for the real requirement','Strong decision. Compare the all-in cost, rate, recipient amount and delivery estimate, then select the route that fits the urgency and certainty required.']],best:'compare'}
 };
 const $a=id=>document.getElementById(id);const keys=Object.keys(missions);let current='payment';let answered={};let bestScores={};
 function renderMission(key,reset=true){current=key;const m=missions[key];document.querySelectorAll('.arena-tab').forEach(b=>{const active=b.dataset.mission===key;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});$a('arena-mission-title').textContent=m.title;$a('arena-mission-brief').textContent=m.brief;document.querySelector('.arena-level').textContent=m.level;$a('arena-visual-label').textContent=m.visual;$a('arena-question').textContent=m.question;$a('arena-decision-hint').textContent=m.hint;$a('arena-takeaway-title').textContent=m.takeTitle;$a('arena-takeaway').textContent=m.take;$a('arena-flow').innerHTML='<div class="arena-flow-line"></div>'+m.nodes.map((n,i)=>`<div class="arena-flow-node ${i<2?'complete':i===2?'uncertain':'pending'}"><span>${n[0]}</span><b>${n[1]}</b><small>${n[2]}</small></div>`).join('');m.events.forEach((t,i)=>$a(['arena-event','arena-event-two','arena-event-three'][i]).textContent=t);$a('arena-choices').innerHTML=m.choices.map((c,i)=>`<button class="arena-choice" data-choice="${c[0]}"><span>${String.fromCharCode(65+i)}</span><span><b>${c[1]}</b><small>${c[2]}</small></span><i>↗</i></button>`).join('');$a('arena-feedback').className='arena-feedback';$a('arena-feedback').innerHTML='<span class="feedback-icon">?</span><div><b>Make your call</b><p>The system will reveal the consequence after you choose.</p></div>';$a('arena-next').classList.add('hidden');if(answered[key]&&!reset)showFeedback(answered[key],true);updateScore();}
 function showFeedback(choice,review=false){const m=missions[current];const c=m.choices.find(x=>x[0]===choice);if(!c)return;const correct=choice===m.best;const points=correct?100:35;if(!review){answered[current]=choice;bestScores[current]=Math.max(bestScores[current]||0,points);updateRecommendation(choice);}const box=$a('arena-feedback');box.className='arena-feedback '+(correct?'feedback-good':'feedback-warn');box.innerHTML=`<span class="feedback-icon">${correct?'✓':'↻'}</span><div><b>${correct?'Good call.':'Here is the trade-off.'}</b><p>${c[3]}</p><small>${correct?'MISSION SCORE: 100 / 100':'MISSION SCORE: 35 / 100'}${review?' · Review mode':''}</small></div>`;document.querySelectorAll('#arena-choices .arena-choice').forEach(b=>{b.disabled=true;b.classList.toggle('choice-best',b.dataset.choice===m.best);b.classList.toggle('choice-picked',b.dataset.choice===choice);});$a('arena-next').classList.remove('hidden');$a('arena-next').textContent=current===keys[keys.length-1]?'Review first mission ↻':'Next mission ↗';updateScore();}
 function updateScore(){const score=Object.values(bestScores).reduce((a,b)=>a+b,0);const done=Object.keys(answered).length;$a('arena-score').textContent=String(score).padStart(3,'0');$a('arena-score-progress').style.width=`${done/keys.length*100}%`;$a('arena-progress-label').textContent=`${done} of ${keys.length} missions completed`;document.querySelectorAll('.arena-tab').forEach(b=>b.classList.toggle('mission-done',!!answered[b.dataset.mission]));}
 function updateRecommendation(choice){const m=missions[current];const correct=choice===m.best;let target='payment',title='Start with Payment Rescue.',copy='Begin with a familiar payment, then explore how risk and records shape the outcome.',label='Start mission 01 ↗';if(current==='payment'){target=correct?'recon':'payment';title=correct?'Next: Find the Mismatch.':'Recommended: replay Payment Rescue.';copy=correct?'You have seen why a timeout needs a status check. Now test how systems handle records that do not agree.':'Review the difference between a failed payment and an unknown outcome, then try the decision again.';label=correct?'Try mission 03 ↗':'Replay mission 01 ↻';}else if(current==='fraud'){target=correct?'recon':'fraud';title=correct?'Next: Find the Mismatch.':'Recommended: revisit Fraud Detective.';copy=correct?'You balanced control with customer fairness. Next, practise evidence-based investigation in reconciliation.':'Review why a risk signal should trigger proportionate verification rather than an automatic extreme response.';label=correct?'Try mission 03 ↗':'Replay mission 02 ↻';}else if(current==='recon'){target=correct?'global':'recon';title=correct?'Next: Cross-Border Choice.':'Recommended: revisit the records.';copy=correct?'You used evidence instead of forcing totals to match. Now compare cost, speed and transparency across transfer routes.':'Check references and event history before changing records. An auditable correction matters more than a neat total.';label=correct?'Try mission 04 ↗':'Replay mission 03 ↻';}else{target=correct?'fraud':'global';title=correct?'Next: Fraud Detective.':'Recommended: compare the transfer options again.';copy=correct?'You compared the whole outcome rather than one headline number. Next, apply the same judgement to risk and customer protection.':'Revisit total cost, recipient amount and delivery confidence before selecting a route.';label=correct?'Try mission 02 ↗':'Replay mission 04 ↻';}$a('arena-recommendation-title').textContent=title;$a('arena-recommendation-copy').textContent=copy;$a('arena-recommendation-action').textContent=label;$a('arena-recommendation-action').dataset.mission=target;$a('arena-recommendation-action').dataset.replay=(!correct?'1':'0');}
 $a('arena-recommendation-action').addEventListener('click',e=>{const b=e.currentTarget;const target=b.dataset.mission;if(b.dataset.replay==='1'){delete answered[target];delete bestScores[target];}renderMission(target);});
 document.querySelectorAll('.arena-tab').forEach(b=>b.addEventListener('click',()=>renderMission(b.dataset.mission)));$a('arena-choices').addEventListener('click',e=>{const b=e.target.closest('[data-choice]');if(!b||b.disabled)return;showFeedback(b.dataset.choice);});$a('arena-next').addEventListener('click',()=>{const i=keys.indexOf(current);renderMission(keys[(i+1)%keys.length]);});$a('arena-replay').addEventListener('click',()=>{delete answered[current];delete bestScores[current];renderMission(current);});renderMission('payment');
})();

(function intro(){
 const el=$('#intro');
 if(!el)return;
 const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 let seen=false;
 try{seen=sessionStorage.getItem('ftsl-intro-seen')==='1';}catch(_error){}
 if(reduce||seen){el.classList.add('is-done');return;}
 const bar=$('#intro-progress-bar');
 const status=$('#intro-status');
 const line=$('#intro-line');
 const subline=$('#intro-subline');
 const phases=[
  {at:0,line:'Every payment begins a journey.',sub:'Follow the connections behind the transaction.',status:'Tracing the first connection'},
  {at:.2,line:'A signal moves through the system.',sub:'Apps, payment rails and institutions work together.',status:'Connecting the essential stages'},
  {at:.4,line:'Follow the money. Understand the system.',sub:'FinTech Systems Lab connects the layers behind each transaction.',status:'The system comes into focus'},
  {at:.6,line:'Created and curated by G. Hari Charan.',sub:'An independent exploration of financial technology.',status:'Prepared for exploration'},
  {at:.8,line:'Understand how finance moves.',sub:'Welcome to FinTech Systems Lab.',status:'Entering the lab'}
 ];
 const duration=20000;
 let start=performance.now(),done=false,current=-1;
 function finish(){
  if(done)return;
  done=true;
  try{sessionStorage.setItem('ftsl-intro-seen','1');}catch(_error){}
  el.classList.add('is-done');
 }
 $('#skip-intro').addEventListener('click',finish);
 function tick(now){
  if(done)return;
  const p=Math.min(1,(now-start)/duration);
  bar.style.transform=`scaleX(${p})`;
  const index=Math.min(phases.length-1,Math.floor(p*phases.length));
  if(index!==current){
   current=index;
   const phase=phases[index];
   el.dataset.phase=String(index);
   line.classList.remove('story-enter');
   subline.classList.remove('story-enter');
   line.textContent=phase.line;
   subline.textContent=phase.sub;
   status.textContent=phase.status;
   if(index!==2){line.classList.add('story-enter');subline.classList.add('story-enter');}
  }
  if(p>=1)finish();else requestAnimationFrame(tick);
 }
 requestAnimationFrame(tick);
})();

